import React from 'react'
import ApplicationHeader from './ApplicationHeader'

function ViewApplication() {

    const application = {

        application_number: 'APP-10234',

        loan_type: 'personal',
        loan_type_label: 'Personal Loan',

        status: 'In Process',

        applied_at: '20 Aug 2026',

        customer: {
            name: 'Ravi Kumar',
            phone: '9876543210',
        },

        agent: {
            name: 'Suresh Kumar',
        },

        rm: {
            name: 'Priya Sharma',
        },

    }


    return (

        <div className="p-6 space-y-5">

            <ApplicationHeader
                application={application}
            />

        </div>

    )
}

export default ViewApplication
